#include <algorithm>
#include <cstddef>
#include <utility>

class SampleBlock {
public:
    SampleBlock() = default;

    explicit SampleBlock(std::size_t count)
        : samples_(count ? new float[count]{} : nullptr), count_(count) {}

    ~SampleBlock() { delete[] samples_; }

    // Copying duplicates the audio so the two blocks stay independent.
    SampleBlock(const SampleBlock& other)
        : samples_(other.count_ ? new float[other.count_] : nullptr),
          count_(other.count_) {
        std::copy(other.samples_, other.samples_ + other.count_, samples_);
    }

    SampleBlock& operator=(const SampleBlock& other) {
        if (this != &other) {
            // Allocate first: if new[] throws, *this is still intact.
            float* fresh = other.count_ ? new float[other.count_] : nullptr;
            std::copy(other.samples_, other.samples_ + other.count_, fresh);
            delete[] samples_;
            samples_ = fresh;
            count_ = other.count_;
        }
        return *this;
    }

    // noexcept, and the source is left genuinely empty -- a postcondition this
    // class documents, which is stronger than valid-but-unspecified.
    SampleBlock(SampleBlock&& other) noexcept
        : samples_(std::exchange(other.samples_, nullptr)),
          count_(std::exchange(other.count_, 0)) {}

    // No allocation anywhere on this path, and the self-check keeps
    // `block = std::move(block)` from deleting the buffer it is about to take.
    SampleBlock& operator=(SampleBlock&& other) noexcept {
        if (this != &other) {
            delete[] samples_;
            samples_ = std::exchange(other.samples_, nullptr);
            count_ = std::exchange(other.count_, 0);
        }
        return *this;
    }

    std::size_t count() const noexcept { return count_; }
    float* data() noexcept { return samples_; }

private:
    float* samples_ = nullptr;
    std::size_t count_ = 0;
};

// Self-move leaves the block valid and, per this class's own postcondition,
// still holding exactly what it held before.
void invariants() {
    SampleBlock block{128};
    block = std::move(block);

    SampleBlock taken = std::move(block);
    // Documented, not merely observed:
    if (block.count() != 0) { /* unreachable */ }
}

