#include <string>
#include <utility>
#include <vector>

// Given: a direct owner of a unique resource. It writes its own transfer
// because an int does not implement ownership, and it deletes copying.
class Reservation {
public:
    explicit Reservation(int ticket) : ticket_(ticket) {}
    ~Reservation() { release(); }

    Reservation(const Reservation&) = delete;
    Reservation& operator=(const Reservation&) = delete;

    Reservation(Reservation&& other) noexcept
        : ticket_(std::exchange(other.ticket_, -1)) {}

    Reservation& operator=(Reservation&& other) noexcept {
        if (this != &other) {
            release();
            ticket_ = std::exchange(other.ticket_, -1);
        }
        return *this;
    }

private:
    void release() {
        if (ticket_ >= 0) { /* return the slot to the pool */ }
    }

    int ticket_ = -1;
};

// Rule of zero. Task declares none of the five. Its copy operations are
// implicitly *defined as deleted* because Reservation's are deleted, so Task
// is move-only without a single `= delete` written here; its moves are
// implicitly generated and noexcept because every member's move is.
struct Task {
    Reservation slot;
    std::string name;
    std::vector<int> inputs;
};

// A sink parameter: callers that are finished with a Task hand it over, and
// the only cost is one move into storage.
class Schedule {
public:
    void enqueue(Task task) { pending_.push_back(std::move(task)); }

private:
    std::vector<Task> pending_;
};

void hand_off() {
    Task task{Reservation{7}, "resample", {1, 2, 3}};
    Schedule schedule;
    schedule.enqueue(std::move(task));  // one move; a copy would not compile
}

// If an audit destructor is genuinely required, declaring it would suppress
// the implicit moves and leave only the deleted copies -- making the type
// neither copyable nor movable. Restore the moves explicitly.
struct AuditedTask {
    Reservation slot;
    std::string name;

    AuditedTask(Reservation reservation, std::string label)
        : slot(std::move(reservation)), name(std::move(label)) {}

    AuditedTask(AuditedTask&&) noexcept = default;
    AuditedTask& operator=(AuditedTask&&) noexcept = default;

    ~AuditedTask() { /* write an audit line */ }
};

void audited() {
    AuditedTask first{Reservation{9}, "decode"};
    AuditedTask second = std::move(first);
    (void)second;
}

#include <string>
#include <utility>

// Deliberately neither copyable nor movable: the only way to produce one is
// to construct it directly in its final storage.
class Timing {
public:
    Timing(const char* label, long nanos) : label_(label), nanos_(nanos) {}

    Timing(const Timing&) = delete;
    Timing& operator=(const Timing&) = delete;
    Timing(Timing&&) = delete;
    Timing& operator=(Timing&&) = delete;

    long nanos() const { return nanos_; }

private:
    std::string label_;
    long nanos_;
};

// Guaranteed elision (C++17): the return expression is a prvalue of the
// result type, so no separate temporary ever exists and no copy or move
// constructor is required. This is a language rule -- -O0 does not put a move
// back. It is what lets a noncopyable, nonmovable type be returned at all.
Timing measure(long nanos) {
    return Timing{"frame", nanos};
}

// Both branches still return a prvalue, so both are elided. Written as
// `Timing slow{...}; Timing fast{...}; return quick ? fast : slow;` this would
// not compile: a conditional over two named locals is an lvalue, so it needs
// a copy constructor -- and for a copyable type it would silently make one.
Timing measure_branch(bool quick) {
    if (quick) {
        return Timing{"fast path", 120};
    }
    return Timing{"slow path", 4'800};
}

// A named local is only an *optional* NRVO candidate. Leave it bare: if NRVO
// happens there is no operation at all, and if it does not, the return
// expression is move-eligible and the move constructor runs. Writing
// `return report;` therefore dominates `return std::move(report);`, which
// gives up the free case to guarantee the paid one.
std::string describe(long nanos) {
    std::string report = "took ";
    report += std::to_string(nanos);
    report += "ns";
    return report;
}

// A by-value parameter never lives in the return destination, so NRVO cannot
// apply; this is an implicit move, and adding std::move changes nothing.
std::string annotate(std::string report) {
    report += " (measured)";
    return report;
}

// A subobject is not an NRVO candidate either, and a bare `return pair.first;`
// would copy. std::move is warranted exactly here, where no elision was ever
// available to lose.
struct Pair {
    std::string first;
    std::string second;
};

std::string take_first(Pair pair) {
    return std::move(pair.first);
}

