#include <iostream>
#include <string>
#include <vector>

struct Counter {
    static int copies;
    static int moves;
    Counter() = default;
    Counter(const Counter&) { ++copies; }
    Counter(Counter&&) noexcept { ++moves; }
    Counter& operator=(const Counter&) = default;
    Counter& operator=(Counter&&) noexcept = default;
};
int Counter::copies = 0;
int Counter::moves = 0;

// Before: the audit destructor suppresses the implicit move constructor. The
// implicit *copy* constructor survives, and its const PacketLogBroken&
// parameter binds happily to an xvalue -- so every relocation inside
// std::vector copies the std::string and the std::vector<int> of every
// existing element. Nothing warns; the only symptom is throughput.
struct PacketLogBroken {
    std::string source;
    std::vector<int> sizes;
    Counter probe;

    ~PacketLogBroken() { /* flush the audit line */ }
};

// After: the destructor stays, so state every operation. Defaulted moves are
// conditionally noexcept -- they inherit the promise from std::string,
// std::vector and Counter, all of which move without throwing -- so
// `noexcept = default` is a checked assertion rather than decoration, and
// std::move_if_noexcept now yields an xvalue during reallocation.
struct PacketLog {
    std::string source;
    std::vector<int> sizes;
    Counter probe;

    PacketLog() = default;
    PacketLog(const PacketLog&) = default;
    PacketLog& operator=(const PacketLog&) = default;
    PacketLog(PacketLog&&) noexcept = default;
    PacketLog& operator=(PacketLog&&) noexcept = default;

    ~PacketLog() { /* flush the audit line */ }
};

int main() {
    // reserve(2) makes the third insertion reallocate, without depending on
    // any growth factor: exactly two existing elements get relocated.
    Counter::copies = 0;
    Counter::moves = 0;
    std::vector<PacketLogBroken> broken;
    broken.reserve(2);
    broken.emplace_back();
    broken.emplace_back();
    broken.emplace_back();
    std::cout << Counter::copies << '/' << Counter::moves << '\n';  // 2/0

    Counter::copies = 0;
    Counter::moves = 0;
    std::vector<PacketLog> fixed;
    fixed.reserve(2);
    fixed.emplace_back();
    fixed.emplace_back();
    fixed.emplace_back();
    std::cout << Counter::copies << '/' << Counter::moves << '\n';  // 0/2
}

#include <cstddef>
#include <string>
#include <utility>
#include <vector>

// This type promises more than the library baseline: after a move, the source
// is *empty*, not merely valid-but-unspecified. Callers may therefore write
// `if (list.empty())` on a moved-from EventList and rely on it.
class EventList {
public:
    void record(std::string name) { names_.push_back(std::move(name)); }

    std::size_t size() const noexcept { return names_.size(); }
    bool empty() const noexcept { return names_.empty(); }

    // `= default` would move the member vector, which leaves it valid but
    // unspecified -- in practice usually empty, which is exactly what makes
    // depending on it a portability trap rather than an obvious mistake. The
    // clear() is what turns an observation into a postcondition. Both
    // operations stay noexcept: clear() on a vector cannot throw.
    EventList(EventList&& other) noexcept : names_(std::move(other.names_)) {
        other.names_.clear();
    }

    EventList& operator=(EventList&& other) noexcept {
        if (this != &other) {
            names_ = std::move(other.names_);
            other.names_.clear();
        }
        return *this;
    }

    EventList() = default;
    EventList(const EventList&) = default;
    EventList& operator=(const EventList&) = default;

private:
    std::vector<std::string> names_;
};

// The guarantee the standard actually gives, and what may be done with it.
void baseline() {
    std::string label = "keydown";
    std::string owner = std::move(label);

    // Allowed: assign a fresh value. This is what makes `label` useful again,
    // and every read after it is well defined.
    label = "keyup";

    // Allowed: call an operation with no preconditions, and destroy it.
    label.clear();

    // NOT to be relied on: `assert(label.empty())` right after the move.
    // Implementations commonly do empty a moved-from string -- and a short
    // string may not even be touched by the move -- so the observation is
    // real and still unportable.
}

void stronger() {
    EventList session;
    session.record("keydown");
    session.record("keyup");

    EventList archived = std::move(session);
    // Guaranteed by this class, not by the library:
    bool reusable = session.empty() && session.size() == 0;
    (void)reusable;
    (void)archived;

    session.record("resume");  // a moved-from object is assignable and usable
}

