#include <string>
#include <utility>
#include <vector>

class Playlist {
public:
    // The bug: `title` is a const std::string&, so std::move(title) produces a
    // const std::string&&. That cannot bind to string's move constructor
    // (std::string&&), and overload resolution falls back to the copy
    // constructor taking const std::string&. std::move did produce an xvalue;
    // the best viable overload merely happened to be the copy. The move is
    // requested and silently refused -- one full allocation per call, and the
    // std::move reads like it is preventing exactly that.
    void add_broken(const std::string& title) {
        titles_.push_back(std::move(title));
    }

    // Fix: take the sink parameter by value, then move out of it. A caller
    // passing a prvalue constructs the parameter directly and pays one move
    // into storage; a caller passing std::move(name) pays one move into the
    // parameter and one more into storage; a caller passing a named lvalue
    // pays one copy plus one move, which is the honest price of retaining it.
    void add(std::string title) {
        titles_.push_back(std::move(title));
    }

    // Read-only access retains nothing, so const& is right here and there is
    // nothing to move.
    bool contains(const std::string& title) const {
        for (const std::string& entry : titles_) {
            if (entry == title) {
                return true;
            }
        }
        return false;
    }

private:
    std::vector<std::string> titles_;
};

void usage() {
    Playlist playlist;

    playlist.add("Rain");                 // prvalue: constructs in place, one move

    std::string keeper = "Static";
    playlist.add(keeper);                 // lvalue: one copy, then one move
    playlist.add(std::move(keeper));      // xvalue: one move, then one move
    keeper = "Drift";                     // fresh value before any further use

    // Never do this: const on an object that must transfer ownership.
    // std::move preserves const, so this copies.
    const std::string pinned = "Anchor";
    playlist.add(std::move(pinned));      // copies, silently
}
